1	import { Button } from "@/shared/ui/button";
2	import {
3	  CommandDialog,
4	  CommandEmpty,
5	  CommandGroup,
6	  CommandInput,
7	  CommandItem,
8	  CommandList,
9	} from "@/shared/ui/command";
10	import {
11	  Dialog,
12	  DialogContent,
13	  DialogDescription,
14	  DialogFooter,
15	  DialogHeader,
16	  DialogTitle,
17	} from "@/shared/ui/dialog";
18	import { Input } from "@/shared/ui/input";
19	import type { SettingsSectionId } from "@/features/settings/lib/sections";
20	import { useCommandPaletteCommands } from "../hooks/use-command-palette-commands";
21	
22	type CommandPaletteProps = {
23	  onOpenSettings: (section: SettingsSectionId) => void;
24	  onOpenFeed: () => void;
25	  onOpenArchive: () => void;
26	  onNewRecording: () => void;
27	  onImportHandwriting: () => void;
28	};
29	
30	/**
31	 * Context-aware command palette (⌘K / Ctrl+K). The hook owns the live command
32	 * list and modal state; this component only renders the dialogs.
33	 */
34	export function CommandPalette({
35	  onOpenSettings,
36	  onOpenFeed,
37	  onOpenArchive,
38	  onNewRecording,
39	  onImportHandwriting,
40	}: CommandPaletteProps) {
41	  const {
42	    open,
43	    setOpen,
44	    groups,
45	    runCommand,
46	    moveDialogOpen,
47	    setMoveDialogOpen,
48	    destinationPath,
49	    setDestinationPath,
50	    submitMoveToFolder,
51	    setMoveTargets,
52	  } = useCommandPaletteCommands({
53	    onOpenSettings,
54	    onOpenFeed,
55	    onOpenArchive,
56	    onNewRecording,
57	    onImportHandwriting,
58	  });
59	
60	  return (
61	    <>
62	      <CommandDialog open={open} onOpenChange={setOpen}>
63	        <CommandInput placeholder="Type a command or search…" />
64	        <CommandList>
65	          <CommandEmpty>No matching commands.</CommandEmpty>
66	          {groups.map((group) => (
67	            <CommandGroup key={group.heading} heading={group.heading}>
68	              {group.items.map((command) => {
69	                const Icon = command.icon;
70	                return (
71	                  <CommandItem
72	                    key={command.id}
73	                    keywords={command.keywords}
74	                    onSelect={() => runCommand(command)}
75	                  >
76	                    <Icon className="text-muted-foreground" />
77	                    <span>{command.label}</span>
78	                  </CommandItem>
79	                );
80	              })}
81	            </CommandGroup>
82	          ))}
83	        </CommandList>
84	      </CommandDialog>
85	
86	      <Dialog
87	        open={moveDialogOpen}
88	        onOpenChange={(nextOpen) => {
89	          setMoveDialogOpen(nextOpen);
90	          if (!nextOpen) {
91	            setDestinationPath("");
92	            setMoveTargets([]);
93	          }
94	        }}
95	      >
96	        <DialogContent>
97	          <DialogHeader>
98	            <DialogTitle>Move notes to folder</DialogTitle>
99	            <DialogDescription>
100	              Enter a folder path. Missing folders will be created.
101	            </DialogDescription>
102	          </DialogHeader>
103	          <div className="grid gap-2">
104	            <Input
105	              autoFocus
106	              value={destinationPath}
107	              onChange={(event) => setDestinationPath(event.target.value)}
108	              placeholder="Events/Wedding/Photos"
109	              onKeyDown={(event) => {
110	                if (event.key === "Enter") {
111	                  event.preventDefault();
112	                  void submitMoveToFolder();
113	                }
114	              }}
115	            />
116	          </div>
117	          <DialogFooter>
118	            <Button
119	              type="button"
120	              variant="outline"
121	              onClick={() => {
122	                setMoveDialogOpen(false);
123	                setDestinationPath("");
124	                setMoveTargets([]);
125	              }}
126	            >
