};

type PaletteGroup = {
  heading: string;
  items: PaletteCommand[];
};

type UseCommandPaletteCommandsArgs = CommandPaletteProps;

const folderName = (path: string) => path.split("/").pop() || path;

export function useCommandPaletteCommands({
  onOpenSettings,
  onOpenFeed,
  onOpenArchive,
  onNewRecording,
  onImportHandwriting,
}: UseCommandPaletteCommandsArgs) {
