    });
  }
  if (folderTargets.length === 1 && !isSystemFolder(folderTargets[0])) {
    const folder = folderTargets[0];
    selectionCommands.push({
      id: "new-note-in-folder",
      label: `New note in "${folderName(folder)}"`,
      icon: FilePlusIcon,
      keywords: ["create", "add"],
      run: () => void createNewNote(folder),
