      id: "rename-folder",
      label: `Rename "${folderName(folder)}"`,
      icon: PencilIcon,
      run: () => startRenameFolder(folder),
    });
  }
  if (removableFolders.length > 0) {
    selectionCommands.push({
      id: "delete-folders",
