      label: "Go to Feed",
      icon: InboxIcon,
      keywords: ["home", "notes"],
      run: onOpenFeed,
    },
    {
      id: "go-archive",
      label: "Go to Archive",
      icon: ArchiveIcon,
      keywords: ["trash", "archieve"],
      run: onOpenArchive,
    },
    {
      id: "open-settings",
      label: "Open Settings",
      icon: SettingsIcon,
      keywords: ["preferences", "config"],
      run: () => onOpenSettings("general"),
    },
    {
      id: "import-apple-notes",
      label: "Import Apple Notes…",
      icon: DownloadIcon,
      keywords: ["import", "apple", "migrate"],
